/** Raw workspace consumers receive the same generated bytes as Bazel's immutable output tree. */
import { spawn, spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  chmodSync,
  copyFileSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { hostname, tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, expect, test } from 'vitest';

const copies: string[] = [];
afterEach(() => {
  for (const path of copies.splice(0)) rmSync(path, { recursive: true, force: true });
});

function fixture() {
  const root = mkdtempSync(join(tmpdir(), 'proto-materialize-'));
  copies.push(root);
  const proto = join(root, 'proto');
  const tree = join(root, 'bin/proto/materialized');
  mkdirSync(join(proto, 'tools'), { recursive: true });
  copyFileSync(join(import.meta.dirname, '../tools/ensure.mjs'), join(proto, 'tools/ensure.mjs'));
  const files = {
    'ts/example/v1/example_pb.ts': '// generated TypeScript\n',
    'py/example/v1/example.py': '# generated Python\n',
  };
  const outputs: Record<string, string> = {};
  for (const [name, text] of Object.entries(files)) {
    const filename = join(tree, name);
    mkdirSync(filename.slice(0, filename.lastIndexOf('/')), {
      recursive: true,
    });
    writeFileSync(filename, text);
    outputs[name.replace(/^py\//, 'python/src/ziyixi_proto/')] = createHash('sha256').update(text).digest('hex');
  }
  const manifest = { version: 2, inputs: { 'buf.lock': 'synthetic' }, outputs };
  writeFileSync(join(tree, 'manifest.json'), JSON.stringify(manifest));
  const bazel = join(root, 'bazel');
  writeFileSync(
    `${bazel}.mjs`,
    `import { appendFileSync } from 'node:fs';\nappendFileSync(${JSON.stringify(join(root, 'calls'))}, process.argv.slice(2).join(' ') + '\\n');\nif (process.env.FAIL_BUILD && process.argv[2] === 'build') process.exit(1);\nif (process.argv[2] === 'info') console.log(${JSON.stringify(join(root, 'bin'))});\n`,
  );
  writeFileSync(bazel, `#!/bin/sh\nexec ${JSON.stringify(process.execPath)} ${JSON.stringify(`${bazel}.mjs`)} "$@"\n`);
  chmodSync(bazel, 0o755);
  const env = { ...process.env, BAZEL: bazel };
  const args = [join(proto, 'tools/ensure.mjs')];
  const run = (extra: Record<string, string> = {}) =>
    spawnSync(process.execPath, args, {
      cwd: root,
      env: { ...env, ...extra },
      encoding: 'utf8',
    });
  return { root, proto, tree, env, args, run, manifest };
}

test('materializes generated modules and preserves handwritten runtime and installed dependencies', () => {
  const f = fixture();
  mkdirSync(join(f.proto, 'ts/node_modules'), { recursive: true });
  writeFileSync(join(f.proto, 'ts/wire-json.ts'), '// handwritten\n');
  writeFileSync(join(f.proto, 'ts/node_modules/keep'), 'installed');
  mkdirSync(join(f.proto, 'ts/obsolete'));
  writeFileSync(join(f.proto, 'ts/obsolete/stale.ts'), 'stale');
  const entries = readdirSync(f.tree, { recursive: true, withFileTypes: true });
  for (const entry of entries) chmodSync(join(entry.parentPath, entry.name), entry.isDirectory() ? 0o555 : 0o444);
  try {
    const result = f.run();
    expect(result.status, result.stderr).toBe(0);
  } finally {
    for (const entry of entries) chmodSync(join(entry.parentPath, entry.name), entry.isDirectory() ? 0o755 : 0o644);
  }
  expect(readFileSync(join(f.proto, 'ts/example/v1/example_pb.ts'), 'utf8')).toBe('// generated TypeScript\n');
  expect(readFileSync(join(f.proto, 'python/src/ziyixi_proto/example/v1/example.py'), 'utf8')).toBe(
    '# generated Python\n',
  );
  expect(readFileSync(join(f.proto, 'ts/wire-json.ts'), 'utf8')).toBe('// handwritten\n');
  expect(readFileSync(join(f.proto, 'ts/node_modules/keep'), 'utf8')).toBe('installed');
  expect(existsSync(join(f.proto, 'ts/obsolete'))).toBe(false);
  expect(JSON.parse(readFileSync(join(f.proto, '.generated.json'), 'utf8'))).toEqual(f.manifest);
  expect(readFileSync(join(f.root, 'calls'), 'utf8')).toBe('build //proto:materialized\ninfo bazel-bin\n');
  rmSync(join(f.proto, 'ts/example'), { recursive: true });
  expect(f.run().status).toBe(0);
  expect(existsSync(join(f.proto, 'ts/example/v1/example_pb.ts'))).toBe(true);
});

test('a failed build or invalid manifest leaves the existing generated tree intact', () => {
  const f = fixture();
  expect(f.run().status).toBe(0);
  const before = readFileSync(join(f.proto, '.generated.json'), 'utf8');
  expect(f.run({ FAIL_BUILD: '1' }).status).toBe(1);
  writeFileSync(join(f.tree, 'ts/example/v1/example_pb.ts'), '// corrupted\n');
  const failed = f.run();
  expect(failed.status).toBe(1);
  expect(failed.stderr).toContain('does not match its manifest');
  expect(readFileSync(join(f.proto, 'ts/example/v1/example_pb.ts'), 'utf8')).toBe('// generated TypeScript\n');
  expect(readFileSync(join(f.proto, '.generated.json'), 'utf8')).toBe(before);
  expect(existsSync(join(f.proto, '.generate.lock'))).toBe(false);
});

test('recovers a dead local lock and cleans abandoned staging directories', () => {
  const f = fixture();
  const child = spawnSync(process.execPath, ['-e', '']);
  mkdirSync(join(f.proto, '.generate.lock'));
  writeFileSync(join(f.proto, '.generate.lock/owner.json'), JSON.stringify({ pid: child.pid, host: hostname() }));
  mkdirSync(join(f.proto, '.generate-abandoned'));
  const result = f.run();
  expect(result.status, result.stderr).toBe(0);
  expect(result.stderr).toContain('no longer runs');
  expect(existsSync(join(f.proto, '.generate-abandoned'))).toBe(false);
});

test('concurrent raw consumers serialize materialization and finish with the same bytes', async () => {
  const f = fixture();
  const run = () =>
    new Promise<number | null>((resolve, reject) => {
      const child = spawn(process.execPath, f.args, {
        cwd: f.root,
        env: f.env,
        stdio: 'ignore',
      });
      child.once('error', reject);
      child.once('exit', resolve);
    });
  expect(await Promise.all([run(), run(), run()])).toEqual([0, 0, 0]);
  expect(JSON.parse(readFileSync(join(f.proto, '.generated.json'), 'utf8'))).toEqual(f.manifest);
  expect(existsSync(join(f.proto, '.generate.lock'))).toBe(false);
});
